'use strict';
const groups = [{"id": "centro", "number": "01", "title": "Il centro a piedi", "timing": "UN POMERIGGIO LIBERO QUALSIASI", "color": "pink", "description": "Il centro è piccolo e si gira a piedi. Due strade pedonali, la piazza della cattedrale e una chiesa su una collina a ogni estremità.", "sections": [["A ZONZO", [["realguadalupe", "Andador Real de Guadalupe", "la strada pedonale principale: caffè, negozi d’ambra e tessuti"], ["cathedral", "Cattedrale e Plaza de la Paz", "la facciata barocca gialla sulla piazza principale"], ["walkingtour", "Free walking tour", "a offerta libera; perfetto per il primo pomeriggio", "Le guide possono anche organizzare un temazcal condiviso con altri viaggiatori."], ["kinoki", "Kinoki", "cinema indipendente e caffè con terrazza sul tetto"], ["cerrillo", "Jardín el Cerrillo", "la piazzetta del barrio El Cerrillo"]]], ["DUE CHIESE IN COLLINA", [["guadalupechurch", "Iglesia de Guadalupe", "in cima alla scalinata, all’estremità est di Real de Guadalupe", "Meglio nel tardo pomeriggio, per la luce sui tetti."], ["cerrito", "Cerrito de San Cristóbal", "la scalinata più ripida sul lato ovest, con la vista più ampia"]]]], "note": "La città è a circa 2.200 m. I primi giorni, le scale si fanno con calma."}, {"id": "markets", "number": "02", "title": "Mercati e Santo Domingo", "timing": "UNA MATTINA · I MERCATI RENDONO PRESTO", "color": "green", "description": "Prima il mercato vero, poi le bancarelle d’artigianato attorno alla chiesa, a pochi isolati a nord della piazza principale.", "sections": [["IL MERCATO", [["mercado", "Mercado Municipal", "il mercato di tutti i giorni: frutta e verdura, peperoncini secchi, spezie, resina di copal", "Cerca le corsie di candele per altari e rituali. Chiedi prima di fotografare le persone."]]], ["SANTO DOMINGO", [["santodomingo", "Templo de Santo Domingo", "la facciata barocca rosa, tutta scolpita"], ["caridad", "Mercado de la Caridad y Santo Domingo", "bancarelle d’artigianato attorno alle chiese: ricami, ambra, lana"], ["textiles", "Centro de Textiles del Mundo Maya", "tessitura maya, nell’ex convento accanto alla chiesa"]]]], "note": "Porta banconote piccole e monete per le bancarelle."}, {"id": "ceremonies", "number": "03", "title": "Cerimonie", "timing": "DUE MEZZE GIORNATE SENZA FRETTA", "color": "blue", "description": "Una capanna sudatoria e una cerimonia del cacao, entrambe con una sciamana maya del posto. Nessuna delle due si prenota online, quindi vanno organizzate nei primi giorni.", "sections": [["TEMAZCAL", [["temazcal", "Cerimonia del temazcal", "circa 3 ore, di cui una novantina di minuti dentro la capanna", "500–1.000 pesos a testa, secondo la grandezza del gruppo. Due strade: scrivere a Brooke di Brooke Beyond per il contatto della sciamana, oppure chiedere alle guide del free walking tour un temazcal condiviso.", [["Brooke Beyond · note sul temazcal", "https://brookebeyond.com/san-cris-travel-guide"]]]]], ["CACAO", [["cacao", "Cerimonia del cacao con Xmal", "2–3 ore: un altare, canti, danze e cacao crudo", "Xmal è una sciamana tzotzil di terza generazione e parla un po’ d’inglese. Prima parla con te e costruisce la cerimonia su misura. Prezzo non indicato. Brooke dà il contatto solo via email.", [["Brooke Beyond · cerimonia del cacao", "https://brookebeyond.com/san-cris-travel-guide"]]]]]], "note": "Scrivere a Brooke prima di arrivare: il contatto arriva via email e può volerci qualche giorno."}, {"id": "green", "number": "04", "title": "Mezze giornate nel verde", "timing": "DOPO IL LAVORO · UNA ALLA VOLTA", "color": "green", "description": "Giardini, un arco di roccia sul fiume e il cimitero. Ognuno a un breve taxi o colectivo dal centro.", "sections": [["GIARDINI", [["jade", "Casa Corazón de Jade", "un museo-giardino di piante locali e medicinali; il tè è compreso nel biglietto"], ["moxviquil", "Giardino delle orchidee Moxviquil", "riserva e giardino di orchidee al margine nord della città"], ["encuentro", "Huerta Parque el Encuentro", "parco e orto a est"]]], ["PIÙ LONTANO", [["arcotete", "El Arcotete", "un arco di calcare sopra un fiume, con brevi sentieri"], ["panteon", "Panteón Municipal", "il cimitero, con tombe dipinte come casette"]]]], "note": "Da novembre piove meno, ma i pomeriggi rinfrescano in fretta. Porta uno strato in più."}, {"id": "museums", "number": "05", "title": "Musei", "timing": "PER UN POMERIGGIO GRIGIO", "color": "pink", "description": "Tre piccoli, un’ora circa ciascuno.", "sections": [["PICCOLI MUSEI", [["nabolom", "Na Bolom", "la casa di Frans e Trudi Blom: fotografie dei maya lacandoni, biblioteca e giardino"], ["amber", "Museo del Ámbar", "l’ambra del Chiapas, nell’ex convento de La Merced"], ["kakaw", "Kakaw Museo del Cacao", "cacao e cioccolato, con assaggio"]]]], "note": "Controlla i giorni di apertura prima di andare: diversi chiudono il lunedì."}, {"id": "work", "number": "06", "title": "Giornate alla scrivania", "timing": "LE MATTINE FERIALI", "color": "blue", "description": "Quattro coworking e sei caffè con un wifi abbastanza buono per lavorare.", "sections": [["COWORKING", [["centralita", "Centralita", "due sedi, Centro ed El Cerrillo; animali ammessi, armadietti, un giorno di prova gratis", "Il loro sito indica il pass giornaliero a 590 pesos, 6 giorni in un mese a 1.200 e 14 giorni a 1.750. Blog più vecchi parlano di 130 al giorno, quindi chiedi all’ingresso. Centro: nei feriali 7:30–21, nel weekend 9–17.", [["Centralita", "https://www.centralitacowork.com/"]]], ["jovel", "Instituto Jovel", "Francisco I. Madero 45; giardino, tavoli all’aperto, caffè e tè compresi", "150 pesos al giorno. Dal lunedì al venerdì, 9–16.", [["Coworking dell’Instituto Jovel", "https://www.institutojovel.com/coworking"]]], ["trececielos", "13 Cielos Hostel & Co-Work", "Francisco I. Madero 58; un ostello con sala coworking", "Circa 6,50 US$ al giorno o 32 US$ a settimana (prezzi del 2024). 8–22."], ["brucken", "Brücken", "il wifi più veloce, fino a 260 Mbps; aperto 24 ore", "Circa 5 US$ al giorno o 50 US$ al mese (prezzi del 2024). A 1,5 km a piedi dal centro."]]], ["CAFFÈ CON WIFI", [["aguacate", "Aguacate Veggie Bar", "wifi veloce, tavoli al chiuso; brunch del weekend 180 pesos"], ["casajasmine", "Casa Jasmine", "ristorante indonesiano e co-living; menú del día 140 pesos"], ["frontera", "Frontera e La Espirituosa", "due caffè con un cortile verde in comune; wifi veloce, menu lungo"], ["sarajevo", "Sarajevo Café", "tanti tavoli; menú del día 150 pesos, pranzo 13–18"], ["kukulpan", "Kukulpan", "panetteria con brunch, succhi freschi e tavoli fuori"], ["astro", "Astro Café", "cortile con sedute comode"]]]], "note": "Coworking e caffè non contano per l’avanzamento: spuntali se ti va."}, {"id": "food", "number": "07", "title": "Mangiare e bere", "timing": "QUANDO ABBIAMO FAME", "color": "pink", "description": "Tutto quello che ho salvato sulla mappa, più il distillato locale.", "sections": [["MANGIARE", [["comal", "Comal, Cocina de Barro", "cucina in pentole di terracotta"], ["achiote", "Achiote Cochinita Pibil", "tacos e tortas di cochinita pibil"], ["catanzaro", "Trattoria Catanzaro", "italiano"], ["bangcook", "Bangcook Tailandés", "thailandese"], ["casadeahn", "Casa de Ahn", "salvato sulla mia mappa"]]], ["CAFFÈ, PANE E CIOCCOLATO", [["xut", "XUT Café de Chiapas", "caffè del Chiapas"], ["roots", "Panadería Artesanal Roots", "panetteria artigianale"], ["jangala", "Jangala", "chocolatería: cacao, gelato e un laboratorio di cioccolato"]]], ["BERE", [["pox", "Un assaggio di pox", "il distillato chiapaneco di mais e canna da zucchero; si pronuncia “posh”"]]]], "note": "Mangiare e bere non contano per l’avanzamento."}, {"id": "sumidero", "number": "SAB", "title": "Cañón del Sumidero e Chiapa de Corzo", "timing": "IL NOSTRO PRIMO SABATO · UNA GIORNATA INTERA", "color": "blue", "weekend": true, "description": "Una barca tra pareti alte fino a un chilometro, i belvedere dall’alto, poi la vecchia cittadina sul fiume. È circa 1.700 m più in basso di San Cristóbal, quindi fa caldo.", "table": {"caption": "Come fare il canyon", "map": "Mappa", "days": [["Tour · salvati su GetYourGuide", [["8–9 ore", "★ Canyon, belvedere e Chiapa de Corzo", "Barca, belvedere e cittadina. Da 68 € a testa; voto 4,6.", "Partenza da San Cristóbal", "Cañón del Sumidero embarcadero Chiapa de Corzo", "https://www.getyourguide.com/san-cristobal-de-las-casas-l2166/san-cristobal-canyon-viewpoints-chiapa-de-corzo-tour-t112135/"], ["8 ore", "Cañón del Sumidero e Chiapa de Corzo in barca", "Il più caro, con pickup in hotel. Da 141 € a testa; voto 4,6.", "Pickup a San Cristóbal", "Chiapa de Corzo Chiapas", "https://www.getyourguide.com/san-cristobal-de-las-casas-l2166/san-cristobal-sumidero-canyon-and-chiapa-de-corzo-tour-t593840/"]]], ["Per conto nostro", [["Tutto il giorno", "Autobus, poi colectivo fino a Chiapa de Corzo", "Le barche condivise partono dall’imbarcadero quando sono piene; circa 230–280 pesos a testa. Così niente belvedere.", "Circa 1 ora e mezza a tratta", "Embarcadero Chiapa de Corzo"]]]]}, "sections": [["IL CANYON", [["canyonboat", "In barca nel canyon", "circa due ore sul Grijalva: coccodrilli, scimmie ragno, la cascata Albero di Natale"], ["miradores", "I belvedere del canyon", "a guardare giù dritto dal bordo"]]], ["CHIAPA DE CORZO", [["lapila", "La Pila", "la fontana in mattoni del Cinquecento sulla piazza principale"], ["chiapawander", "Due passi e pranzo sul fiume", "da provare il pozol, la bevanda fredda di cacao e mais"]]]], "note": "Cappello, crema solare e uno strato per la barca: sull’acqua si va veloci e tira vento, poi in paese fa caldo."}, {"id": "chamula", "number": "SAB", "title": "San Juan Chamula e Zinacantán", "timing": "IL NOSTRO SECONDO SABATO · MATTINA FUORI, POMERIGGIO LIBERO", "color": "pink", "weekend": true, "description": "Due villaggi maya tzotzil a dieci chilometri dalla città. Una chiesa come nessun’altra e la casa di una famiglia di tessitrici.", "table": {"caption": "Come arrivare ai villaggi", "map": "Mappa", "days": [["Tour · salvato su GetYourGuide", [["5 ore", "★ Tour guidato di Chamula e Zinacantán", "Entrambi i villaggi con una guida, che aiuta: senza, la chiesa si capisce poco. Da 19 € a testa; voto 4,5.", "Partenza da San Cristóbal", "San Juan Chamula Chiapas", "https://www.getyourguide.com/san-cristobal-de-las-casas-l2166/from-san-cristobal-chamula-and-zinacantan-guided-tour-t112333/"]]], ["Colectivo · con i nostri tempi", [["20 minuti", "Colectivo dal mercato", "Circa 25 pesos a testa a corsa. Un secondo colectivo collega i due villaggi.", "10 km a nord-ovest", "San Juan Chamula Chiapas"]]]]}, "sections": [["SAN JUAN CHAMULA", [["chamulachurch", "Iglesia de San Juan Bautista", "aghi di pino sul pavimento, centinaia di candele, niente banchi", "Circa 25 pesos per entrare. Dentro niente foto, mai: il telefono resta in tasca."], ["chamulasquare", "La piazza e il mercato", "lana, frutta e uomini in tuniche di lana bianca o nera"]]], ["ZINACANTÁN", [["zinacantan", "La casa di una famiglia di tessitrici", "telai a cintura, fiori ricamati e tortillas appena tolte dal comal"], ["sanlorenzo", "Iglesia de San Lorenzo", "la chiesa bianca, piena di fiori freschi"]]]], "note": "La domenica è il grande giorno di mercato a Chamula, quindi il sabato è più tranquillo. Rientro nel primo pomeriggio, con il resto della giornata libero."}];

const optional = [["palenque", "Palenque, Agua Azul e Misol-Há", "una giornata lunghissima: 14–19 ore, con partenza verso le 4", "Un forse. Il tour salvato su GetYourGuide parte da 78 € a testa. I blocchi stradali possono chiudere la strada senza preavviso: controllare il giorno prima. Una notte a Palenque sarebbe più gentile.", [["GetYourGuide · tour di Palenque", "https://www.getyourguide.com/san-cristobal-de-las-casas-l2166/san-cris-agua-azul-misol-ha-z-arq-palenq-spanish-t457578/"]]]];
const KEY='frolicking-nicky-san-cristobal-v1';
let checked={}; let storageOK=true;
try { const saved=JSON.parse(localStorage.getItem(KEY)||'{}'); if(saved && typeof saved==='object' && !Array.isArray(saved)) checked=saved; } catch {storageOK=false;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const OPTIONAL_IDS=new Set(["centralita", "jovel", "trececielos", "brucken", "aguacate", "casajasmine", "frontera", "sarajevo", "kukulpan", "astro", "comal", "achiote", "catanzaro", "bangcook", "casadeahn", "xut", "roots", "jangala", "pox"]);
const countedIds=()=>groups.filter(()=>true).flatMap(g=>g.sections.flatMap(s=>s[1].map(r=>r[0]))).filter(id=>!OPTIONAL_IDS.has(id));
function item(row,extra=false) {const [id,title,desc,note,links]=row;return `<label class="task${checked[id]===true?' completed':''}"><input type="checkbox" id="${esc(id)}" data-extra="${extra}" ${checked[id]===true?'checked':''}><span class="checkmark" aria-hidden="true"></span><span class="task-copy"><span class="task-title">${esc(title)}</span> <span class="specialty">(${esc(desc)})</span>${note?`<span class="task-note">${esc(note)}</span>`:''}${links&&links.length?`<span class="fn-task-links">${links.map(([l,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(l)} ↗︎</a>`).join('')}</span>`:''}</span></label>`;}
const PHOTOS={"centro": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Catedral_de_San_Crist%C3%B3bal_de_las_Casas_1.jpg/1280px-Catedral_de_San_Crist%C3%B3bal_de_las_Casas_1.jpg", "La facciata barocca gialla e rossa della cattedrale di San Cristóbal", 1280, 997, "GameOfLight", "CC BY-SA 3.0", "https://commons.wikimedia.org/wiki/File:Catedral_de_San_Crist%C3%B3bal_de_las_Casas_1.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/1/13/San_Cristobal_de_las_Casas%2C_Iglesia_de_Nuestra_Se%C3%B1ora_de_Guadalupe.jpg/1280px-San_Cristobal_de_las_Casas%2C_Iglesia_de_Nuestra_Se%C3%B1ora_de_Guadalupe.jpg", "La Iglesia de Guadalupe, bianca e oro, in cima alla scalinata", 1280, 853, "Anthony G. Reyes", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:San_Cristobal_de_las_Casas,_Iglesia_de_Nuestra_Se%C3%B1ora_de_Guadalupe.jpg"]]], "markets": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/San_Crist%C3%B3bal_de_Las_Casas%2C_Chiapas%2C_Mexico%2C_2022_-_15.jpg/1280px-San_Crist%C3%B3bal_de_Las_Casas%2C_Chiapas%2C_Mexico%2C_2022_-_15.jpg", "Un banco di frutta sotto ombrelloni colorati al mercato di San Cristóbal", 1280, 976, "Globetrotteur17", "CC BY-SA 2.0", "https://commons.wikimedia.org/wiki/File:San_Crist%C3%B3bal_de_Las_Casas,_Chiapas,_Mexico,_2022_-_15.jpg"]]], "sumidero": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Sumidero_Canyon%2C_Chiapas.jpg/1280px-Sumidero_Canyon%2C_Chiapas.jpg", "Il fiume verde tra le alte pareti del Cañón del Sumidero", 1280, 590, "Sgroey", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Sumidero_Canyon,_Chiapas.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Ca%C3%B1on_del_Sumidero%2C_Chiapas%2C_M%C3%A9xico.jpg/1280px-Ca%C3%B1on_del_Sumidero%2C_Chiapas%2C_M%C3%A9xico.jpg", "Lo sguardo lungo l’acqua dentro il Cañón del Sumidero", 1280, 960, "Christopher Javier Cuenca García", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Ca%C3%B1on_del_Sumidero,_Chiapas,_M%C3%A9xico.jpg"]]]};
const fig=([src,alt,w,h,by,lic,url])=>`<figure class="fn-v-photo"><a href="${src}" target="_blank" rel="noopener"><img src="${src}" alt="${esc(alt)}" width="${w}" height="${h}" loading="lazy"></a></figure>`;
const muertosTable=(t,gid)=>{const pick=0;return `<div class="fn-plan-tabs" role="tablist" aria-label="${esc(t.caption)}">${t.days.map(([day],i)=>`<button type="button" role="tab" id="fn-plan-tab-${gid}-${i}" aria-controls="fn-plan-day-${gid}-${i}" aria-selected="${i===pick}" tabindex="${i===pick?0:-1}">${esc(day.split(' · ')[0])}</button>`).join('')}</div>${t.days.map(([day,rows],i)=>`<div class="fn-plan-panel" role="tabpanel" id="fn-plan-day-${gid}-${i}" aria-labelledby="fn-plan-tab-${gid}-${i}"${i===pick?'':' hidden'}>${day.includes(' · ')?`<p class="fn-plan-sub">${esc(day.split(' · ').slice(1).join(' · '))}</p>`:''}<ol class="fn-plan-stops">${rows.map(([when,plan,what,where,q,url])=>`<li${/★/.test(plan)?' class="fn-plan-star"':''}><span class="fn-plan-when">${esc(when)}</span><div><p class="fn-plan-name">${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(plan)} ↗︎</a>`:esc(plan)}</p><p class="fn-plan-what">${esc(what)}</p><p class="fn-plan-where">${esc(where)} <a class="fn-plan-map" href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent(q)}" target="_blank" rel="noopener noreferrer">${esc(t.map)}</a></p></div></li>`).join('')}</ol></div>`).join('')}`;};
let rowN=0;
document.querySelector('#itinerary').innerHTML=groups.map(g=>`<section id="${g.id}" class="outing fn-split ${g.color} ${g.weekend?'weekend':''}" aria-labelledby="title-${g.id}"><div class="outing-heading"><span class="number" aria-hidden="true">${g.number}</span><div><p class="eyebrow">${g.timing}</p><h2 id="title-${g.id}">${g.title}</h2><p class="section-desc">${g.description}</p></div><span class="group-count" id="count-${g.id}" aria-label="Completamento della sezione"></span></div>${g.table?`<div class="fn-plan-wrap">${muertosTable(g.table,g.id)}</div>`:''}<div class="outing-body fn-split-body"${g.sections.length?'':' hidden'}>${g.sections.map(([title,rows],si)=>{const ps=(PHOTOS[g.id]||[])[si]||[];const card=`<div class="task-group"><h3>${title}</h3>${rows.map(r=>item(r,OPTIONAL_IDS.has(r[0]))).join('')}</div>`;return ps.length?`<div class="fn-v-row${rowN++%2?' fn-v-rev':''}"><div class="fn-v-side">${ps.map(fig).join('')}</div>${card}</div>`:card;}).join('')}</div><div class="outing-note"><p>${g.note}</p>${g.link?`<a href="${g.link[1]}" target="_blank" rel="noopener noreferrer">${g.link[0]} ↗︎</a>`:''}</div></section>`).join('');
document.querySelectorAll('.fn-plan-tabs').forEach(list=>{const tabs=[...list.querySelectorAll('[role=tab]')];const show=(tab,focus)=>{tabs.forEach(b=>{const on=b===tab;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;document.getElementById(b.getAttribute('aria-controls')).hidden=!on;});if(focus)tab.focus();};tabs.forEach((b,i)=>{b.addEventListener('click',()=>show(b));b.addEventListener('keydown',e=>{const n={ArrowRight:i+1,ArrowLeft:i-1,Home:0,End:tabs.length-1}[e.key];if(n===undefined)return;e.preventDefault();show(tabs[(n+tabs.length)%tabs.length],true);});});});
document.querySelector('#optional-list').innerHTML=optional.map(r=>item(r,true)).join('');
function update(announce=false){const mainIds=countedIds();const done=mainIds.filter(id=>checked[id]===true).length;const percent=Math.round(done/mainIds.length*100);document.querySelector('#progress-count').textContent=done;document.querySelector('#progress-total').textContent=`su ${mainIds.length} posti e momenti`;document.querySelector('#percent').textContent=percent+'%';document.querySelector('#progress').value=percent;document.querySelector('#progress').textContent=percent+'%';groups.forEach(g=>{const inactive=false;const ids=g.sections.flatMap(s=>s[1].map(r=>r[0])).filter(id=>!OPTIONAL_IDS.has(id));document.querySelector('#count-'+g.id).hidden=!ids.length;document.querySelector('#count-'+g.id).textContent=inactive?"Alternativa: non conta nella checklist":`${ids.filter(id=>checked[id]===true).length} / ${ids.length}`;});const extra=[...optional.map(r=>r[0]),...OPTIONAL_IDS].filter(id=>checked[id]===true).length;document.querySelector('#extra-count').textContent=`${extra} ${extra===1?'tappa facoltativa fatta':'tappe facoltative fatte'}`;document.querySelector('#save-note').textContent=storageOK?'Progressi salvati su questo dispositivo.':'Le spunte funzionano qui, ma in questo browser il salvataggio non è disponibile.';if(announce)document.querySelector('#announcement').textContent=`${done} su ${mainIds.length} voci principali completate. ${extra} tappe facoltative fatte.`;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(checked));storageOK=true;}catch{storageOK=false;}}
document.addEventListener('change',e=>{if(!e.target.matches('.task input'))return;checked[e.target.id]=e.target.checked;e.target.closest('.task').classList.toggle('completed',e.target.checked);persist();update(true);});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{const next=JSON.parse(e.newValue||'{}');checked=next&&typeof next==='object'&&!Array.isArray(next)?next:{};}catch{checked={};}document.querySelectorAll('.task input').forEach(el=>{el.checked=checked[el.id]===true;el.closest('.task').classList.toggle('completed',el.checked);});update();});
const dialog=document.querySelector('#reset-dialog');document.querySelector('#reset').addEventListener('click',()=>dialog.showModal());document.querySelector('#cancel-reset').addEventListener('click',()=>dialog.close());document.querySelector('#confirm-reset').addEventListener('click',()=>{checked={};persist();document.querySelectorAll('.task input').forEach(el=>{el.checked=false;el.closest('.task').classList.remove('completed');});update(true);dialog.close();});
update();
